cat /proc/uptime; cat /var/opt/mgu-deploy/last-shutdown /var/opt/mgu-deploy/safe-mode-count; ls /var/opt/mgu-deploy/safe-mode 2>&1; echo ---; systemctl is-active mgu-uplink aapd connman wpa_supplicant; systemctl status mgu-uplink --no-pager 2>&1 | grep -E "Active|ExecStartPre"; systemctl --failed --no-pager | head -5; echo ---; ps | grep -c "/var/opt/.*/current/" ; ps | grep bootlog | grep -v grep; find /etc/systemd -name "*devlink-wifilog*"; awk "\$2==\"/\"{print \$4}" /proc/mounts | cut -d, -f1 | tail -1; echo ---; /var/opt/mgu-uplink/current/mgu-uplink status -c /var/opt/mgu-uplink/current/mgu-uplink.conf 2>&1 | head -4; sqlite3 /var/opt/public/sin/recmgr/recmgr_stats.db "select max(CrashKey) from Crash"; for n in wlan0 p2p-wlan0-0 wlan_bridge; do echo "$n=$(cat /sys/class/net/$n/operstate)"; done
